  "confidence": "high",
  "source_coverage": [
    "TARGET.md",
    "CONTEXT.md: notes/integrated_wave_variance.tex",
    "CONTEXT.md: notes/integrated_positive_gram.tex",
    "CONTEXT.md: notes/integrated_occupation_ceiling.tex",
